def wordPattern(self, pattern: str, s: str) -> bool:
    words = s.split(' ')
    if len(pattern) != len(words):
        return False
    c2w: dict[str, str] = {}
    w2c: dict[str, str] = {}
    for c, w in zip(pattern, words):
        if c in c2w and c2w[c] != w:
            return False
        if w in w2c and w2c[w] != c:
            return False
        c2w[c] = w
        w2c[w] = c
    return True

