public boolean wordPattern(String pattern, String s) {
    String[] words = s.split(" ");
    if (pattern.length() != words.length) return false;
    Map<Character, Integer> fp = new HashMap<>();
    Map<String, Integer> fw = new HashMap<>();
    for (int i = 0; i < words.length; i++) {
        char c = pattern.charAt(i);
        String w = words[i];
        Integer ip = fp.putIfAbsent(c, i);
        Integer iw = fw.putIfAbsent(w, i);
        int firstP = (ip == null) ? i : ip;
        int firstW = (iw == null) ? i : iw;
        if (firstP != firstW) return false;
    }
    return true;
}

